  "result": "[{\"event_id\": \"evt_aesrg_0002\", \"calendar_id\": \"cal_finance\", \"summary\": \"Call servicer - escrow shortage election - final\", \"description\": \"Ask for the 12-month spread in writing and the disbursement schedule used for the hazard premium. Reference the annual disclosure statement. Added after the reset notice arrived.\", \"location\": \"phone\", \"start\": {\"dateTime\": \"2026-06-02T17:00:00Z\"}, \"end\": {\"dateTime\": \"2026-06-02T17:30:00Z\"}, \"all_day\": false, \"status\": \"confirmed\", \"created_at\": \"2026-04-30T09:00:00Z\", \"updated_at\": \"2026-06-02T09:00:00Z\", \"recurrence_rule\": null, \"parent_event_id\": null, \"attendees\": [], \"reminders\": [{\"method\": \"popup\", \"minutes_before\": 30}]}, {\"event_id\": \"evt_aesrg_0009\", \"calendar_id\": \"cal_finance\", \"summary\": \"SMUD budget-billing review - ref 034-0291-017\", \"description\": \"Decide whether to level payments at about $214/mo before the summer AC peak on the 1998 unit. Blocked out; do not schedule over this.\", \"location\": \"online\", \"start\": {\"dateTime\": \"2026-06-06T11:00:00Z\"}, \"end\": {\"dateTime\": \"2026-06-06T11:30:00Z\"}, \"all_day\": false, \"status\": \"tentative\", \"created_at\": \"2026-05-31T09:00:00Z\", \"updated_at\": \"2026-06-06T09:00:00Z\", \"recurrence_rule\": null, \"parent_event_id\": null, \"attendees\": [], \"reminders\": [{\"method\": \"popup\", \"minutes_before\": 120}]}, {\"event_id\": \"evt_aesrg_0001\", \"calendar_id\": \"cal_finance\", \"summary\": \"Card statement due - confirmed\", \"description\": \"card_primary statement balance $4,460.00, minimum $111.50. Pay above the minimum; interest posts at 23.75% APR if a balance carries. Blocked out; do not schedule over this.\", \"location\": \"online\", \"start\": {\"dateTime\": \"2026-06-08T16:00:00Z\"}, \"end\": {\"dateTime\": \"2026-06-08T18:00:00Z\"}, \"all_day\": false, \"status\": \"confirmed\", \"created_at\": \"2026-05-26T09:00:00Z\", \"updated_at\": \"2026-06-